<template>
  <base-layout>
    <v-toolbar v-if="authenticated" flat color="grey lighten-3" height="50">
      <v-toolbar-title class="subheading">Data Dokumen Pabean</v-toolbar-title>
    </v-toolbar>
    <div>
      <div>
        <v-card flat class="pa-3 table-sm table-striped">
          <v-form ref="form">
            <v-layout row wrap class="mb-1">
              <v-flex xs3 class="px-2">
                <vdatepicker
                  :editable="false"
                  label="Tanggal"
                  v-model="filterInputTmp.tanggal"
                  :range="true"
                ></vdatepicker>
              </v-flex>
              <v-flex xs2 class="px-2">
                <v-select
                  :items="dpDropdown[0]"
                  item-value="id_inout"
                  item-text="movement"
                  v-model="filterInputTmp.masukKeluar"
                  label="Masuk Keluar"
                  name="Masuk Keluar"
                  :error-messages="errors.collect('Masuk Keluar')"
                  v-validate="'required'"
                ></v-select>
              </v-flex>
              <v-flex xs4 class="px-2">
                <select-view
                  placeholder="Jenis"
                  v-model="filterInputTmp.jenis"
                  from-file="bctype"
                  name="Jenis"
                  searchable
                  :extra-query-options="jenisQueryOptions"
                ></select-view>
              </v-flex>
              <v-flex xs3 class="px-2">
                <v-select
                  :items="dpDropdown[2]"
                  item-value="id_tujuan"
                  item-text="tujuan"
                  v-model="filterInputTmp.tujuan"
                  label="Tujuan"
                  name="Tujuan"
                  :error-messages="errors.collect('Tujuan')"
                  v-validate="''"
                ></v-select>
              </v-flex>
              <v-flex xs8>
                <v-btn color="primary" @click="submitFilter()">Cari</v-btn>
                <v-btn
                  @click="print()"
                  v-if="user.idRole!='2' && filterInput.masukKeluar != ''"
                  success
                  dark
                  class="blue-grey white--text"
                >Buat Laporan</v-btn>
                <v-btn
                  @click="download()"
                  v-if="user.idRole!='2' && filterInput.masukKeluar != ''"
                  success
                  dark
                  class="green white--text"
                >Export Excel</v-btn>
              </v-flex>
              <v-flex xs4>
                <v-text-field
                  v-if="filterInput.masukKeluar != ''"
                  label="Cari..."
                  append-icon="search"
                  class="mb-2"
                  v-model="searchQuery"
                  hide-details
                ></v-text-field>
              </v-flex>
            </v-layout>
            <!-- <v-divider></v-divider> -->
          </v-form>
          <table-view
            v-show="filterInput.masukKeluar != ''"
            from-file="pabean"
            :extra-query-options="dataExtraQueryOptions"
            :is-refresh="state.isRefresh"
            :get-items="(data)=> { this.data = data; }"
            :get-columns="(columns)=> { this.columns = columns; }"
            :response-callback="responseCallback"
          ></table-view>
          <div
            v-if="filterInput.masukKeluar != ''"
            class="my-2 font-weight-bold"
          >Total dokumen : {{ this.totalDokumenCurrentPage }} / {{ this.totalDokumen }}</div>
        </v-card>
      </div>
    </div>
    <query-service
      v-model="dpDropdown"
      from-file="dp_dropdown"
      :extra-query-options="dpDropdownQueryOptions"
    />
    <query-service
      v-model="settingPrintModel"
      from-file="setting_print"
      :extra-query-options="settingPrintQueryOptions"
    />
  </base-layout>
</template>

<script>
import moment from "moment";
import _filter from "lodash/filter";
import _debounce from "lodash/debounce";

import { post } from "@/utils/proxy";
import { print, excel } from "@/utils/exportDownload";

import { API_LOCATION } from "@/constants";

export default {
  data() {
    return {
      q: "",
      state: {
        isRefresh: false
      },
      filterInput: {
        tanggal: [new Date(), new Date()],
        masukKeluar: "",
        tujuan: "",
        jenis: ""
      },
      filterInputTmp: {
        tanggal: [new Date(), new Date()],
        masukKeluar: "",
        tujuan: "",
        jenis: ""
      },
      data: [],
      columns: [],
      dpDropdown: [],
      settingPrintModel: [],
      pabeanTotalDoc: [],
      base64Header1: "",
      base64Header2: "",
      base64Header3: "",
      searchQuery: "",
      totalDokumen: 0,
      totalDokumenCurrentPage: 0,
      dataGroupByNoDoc: []
    };
  },
  methods: {
    debounce: _debounce(f => {
      f();
    }, 600),
    responseCallback(data) {
      const newData = [];
      let i = 0;
      let prevText01 = "";
      data.forEach(item => {
        let newText01 = "";
        const existData = _filter(
          this.dataGroupByNoDoc,
          o => o.no_docbc === item.no_docbc
        );
        if (existData.length > 0) {
          if (prevText01 !== existData[0].index) {
            i += 1;
            newText01 = existData[0].index;
            prevText01 = newText01;
          }
        }
        newData.push(Object.assign(item, { text01: newText01 }));
      });
      this.totalDokumenCurrentPage = i;
      return newData;
    },
    responseCallbackLaporan(data) {
      const newData = [];
      let i = 1;
      let prevText = "";
      data.forEach(item => {
        let newText01 = "";
        if (prevText !== item.no_docbc) {
          newText01 = i;
          prevText = item.no_docbc;
          i += 1;
        }
        newData.push(Object.assign(item, { text01: newText01 }));
      });
      return newData;
    },
    formatCurrency(value) {
      const val = parseFloat(value, 10);
      return val.toFixed(2).replace(/(\d)(?=(\d\d\d)+(?!\d))/g, "$1,");
    },
    submitFilter() {
      this.$validator.validateAll().then(() => {
        if (!this.errors.any()) {
          const dataExtraQueryOptions = Object.assign(
            {
              GROUP: "no_docbc"
            },
            this.getDataExtraQueryOptions(this.filterInputTmp)
          );
          post("base/table/getData", {
            name: "pabean",
            where: dataExtraQueryOptions
          }).then(response => {
            this.dataGroupByNoDoc = response.data.map((item, index) =>
              Object.assign(item, {
                index: index + 1
              })
            );
            this.totalDokumen = response.data.length;
            this.filterInput = Object.assign({}, this.filterInputTmp);
          });
        } else {
          $(`[name="${this.errors.items[0].field}"]`).focus();
        }
      });
    },
    download() {
      post("base/table/getData", {
        name: "pabean",
        where: {
          AND: this.dataExtraQueryOptions.AND
        }
      }).then(response => {
        excel(
          [
            {
              table: {
                title: `LAPORAN ${this.labelMasukKeluar} BARANG PER DOKUMEN PABEAN PERIODE: ${this.labelPeriode}`,
                fields: this.columns.map(item => ({
                  id: item.value,
                  title: item.text
                })),
                data: this.responseCallbackLaporan(response.data)
              }
            }
          ],
          `LAPORAN DOKUMEN PABEAN`
        );
      });
    },
    print() {
      const rotateImages = [
        post(
          `${API_LOCATION}app/getRotateTextImage?text=LAPORAN ${this.labelMasukKeluar} BARANG&s=24&align=center`
        ),
        post(
          `${API_LOCATION}app/getRotateTextImage?text=PER DOKUMEN PABEAN&s=24&align=center`
        ),
        post(
          `${API_LOCATION}app/getRotateTextImage?text=PERIODE: ${this.labelPeriode}&s=14&align=center`
        )
      ];
      post("base/table/getData", {
        name: "pabean",
        where: {
          AND: this.dataExtraQueryOptions.AND
        }
      }).then(response => {
        Promise.all(rotateImages).then(images => {
          this.base64Header1 = images[0].base64;
          this.base64Header2 = images[1].base64;
          this.base64Header3 = images[2].base64;
          this.printReport(this.responseCallbackLaporan(response.data));
        });
      });
    },
    printReport(data = []) {
      const writeRotatedText = (text, size) => {
        let ctx = "";
        const canvas = document.createElement("canvas");
        canvas.width = 36;
        canvas.height = 700;
        ctx = canvas.getContext("2d");
        ctx.font = `${size}pt Arial`;
        ctx.save();
        ctx.translate(36, 700);
        ctx.rotate(-0.5 * Math.PI);
        ctx.fillStyle = "#000";
        ctx.fillText(text, 0, 0);
        ctx.restore();
        return canvas.toDataURL();
      };

      const customWidths = [];
      const customBody = [];
      const header1 = [];
      const header2 = [];
      const header3 = [];
      const headerColumns = [];
      this.columns.forEach((item, index) => {
        customWidths.push(parseInt(item.width_print, 10));
        if (index === 0) {
          header1.push({
            text: `LAPORAN ${this.labelMasukKeluar} BARANG PER DOKUMEN PABEAN`,
            colSpan: this.columns.length + 1,
            style: "f15",
            alignment: "left",
            border: [false, false, false, false]
          });
          header2.push({
            text: `KAWASAN BERIKAT: ${this.appSettings.nama_pt.toUpperCase()}`,
            colSpan: this.columns.length + 1,
            style: "f15",
            alignment: "left",
            border: [false, false, false, false]
          });
          header3.push({
            text: `PERIODE: ${this.labelPeriode}`,
            colSpan: this.columns.length + 1,
            style: ["f15", "mb25"],
            alignment: "left",
            border: [false, false, false, false]
          });
        } else {
          header1.push({});
          header2.push({});
          header3.push({});
        }

        headerColumns.push({
          text: item.text,
          alignment: item.align,
          bold: true
        });
      });
      customWidths.push("*");
      header1.push({});
      header2.push({});
      header3.push({});
      headerColumns.push({
        text: "",
        border: [false, false, false, false]
      });

      customBody.push(header1);
      customBody.push(header2);
      customBody.push(header3);
      customBody.push(headerColumns);

      data.forEach(item => {
        const bodyRows = [];
        this.columns.forEach(col => {
          const row = {
            text: item[col.value],
            alignment: col.align,
            maxHeight: 15
          };
          if (col.type === "date") {
            row.text = moment(item[col.value]).format(col.options.format);
          }
          if (col.type === "currency") {
            row.text = this.formatCurrency(item[col.value]);
          }
          bodyRows.push(row);
        });
        bodyRows.push({
          text: "",
          border: [false, false, false, false]
        });
        customBody.push(bodyRows);
      });

      const exportedData = [
        {
          colGroups: [
            [
              {
                cTable: {
                  widths: [150, 30, 30, 30, 600, 30, 30, 30],
                  heights: [755],
                  body: [
                    [
                      {
                        text: "",
                        border: [false, false, false, false]
                      },
                      {
                        image: this.base64Header1,
                        alignment: "right",
                        border: [false, false, false, false]
                      },
                      {
                        image: this.base64Header2,
                        alignment: "right",
                        border: [false, false, false, false]
                      },
                      {
                        image: this.base64Header3,
                        alignment: "right",
                        border: [false, false, false, false]
                      },
                      {
                        text: "",
                        border: [false, false, false, false]
                      },
                      {
                        image: writeRotatedText(
                          this.appSettings.nama_pt.toUpperCase(),
                          18
                        ),
                        alignment: "right",
                        border: [false, false, false, false]
                      },
                      {
                        image: writeRotatedText(
                          "DELTA SILICON INDUSTRIAL PARK. JL KRUING I BLOCK L5 NO 3A",
                          12
                        ),
                        alignment: "right",
                        border: [false, false, false, false]
                      },
                      {
                        image: writeRotatedText(
                          "LEMAHABANG, BEKASI. 17550",
                          12
                        ),
                        alignment: "right",
                        border: [false, false, false, false]
                      }
                    ]
                  ]
                }
              },
              {
                cTable: {
                  headerRows: 4,
                  widths: customWidths,
                  body: customBody
                }
              },
              {
                cTable: {
                  widths: [800, "*"],
                  body: [
                    [
                      { text: "", border: [false, false, false, false] },
                      {
                        text: "Kami Bertanggung Jawab Atas",
                        alignment: "left",
                        style: ["f11", "mt50"],
                        border: [false, false, false, false]
                      }
                    ],
                    [
                      { text: "", border: [false, false, false, false] },
                      {
                        text: "Kebenaran Laporan Ini",
                        alignment: "left",
                        style: ["f11"],
                        border: [false, false, false, false]
                      }
                    ],
                    [
                      { text: "", border: [false, false, false, false] },
                      {
                        text: `${this.settingPrint.tempat}, ${moment(
                          this.settingPrint.tanggal
                        )
                          .locale("id")
                          .format("DD MMMM YYYY")}`,
                        alignment: "left",
                        style: ["f11", "mb50"],
                        border: [false, false, false, false]
                      }
                    ],
                    [
                      { text: "", border: [false, false, false, false] },
                      {
                        text: this.settingPrint.nama,
                        alignment: "left",
                        style: ["f11"],
                        border: [false, false, false, false]
                      }
                    ],
                    [
                      { text: "", border: [false, false, false, false] },
                      {
                        text: this.settingPrint.jabatan,
                        alignment: "left",
                        style: ["f11"],
                        border: [false, false, false, false]
                      }
                    ]
                  ]
                }
              }
            ]
          ]
        }
      ];
      const fileName = "Laporan Dokumen Pabean";
      print(exportedData, fileName, "landscape", "A3");
    },
    getDataExtraQueryOptions(filterInput) {
      const extraQueryOptions = {
        AND: {},
        ORDER: {
          no_docbc: "ASC",
          id_doc: "ASC"
        }
      };

      let andOr = false;

      if (filterInput.tanggal !== "") {
        if (filterInput.tanggal[0] !== null) {
          extraQueryOptions.AND["tgl_doc[<>]"] = [
            `${moment(filterInput.tanggal[0]).format("YYYY-MM-DD")} 00:00:00`,
            `${moment(filterInput.tanggal[1]).format("YYYY-MM-DD")} 23:59:59`
          ];
          andOr = true;
        }
      }

      if (filterInput.masukKeluar !== "") {
        extraQueryOptions.AND.id_inout = filterInput.masukKeluar;
        andOr = true;
      } else {
        extraQueryOptions.AND.id_inout = "-";
        andOr = true;
      }

      if (filterInput.tujuan !== "" && filterInput.tujuan !== null) {
        extraQueryOptions.AND.id_tujuan = filterInput.tujuan;
        andOr = true;
      }

      if (filterInput.jenis !== "" && filterInput.jenis !== null) {
        extraQueryOptions.AND.id_type = filterInput.jenis;
        andOr = true;
      }

      if (!andOr) {
        delete extraQueryOptions.AND;
      }

      return extraQueryOptions;
    }
  },
  created() {},
  watch: {
    searchQuery() {
      this.debounce(() => {
        this.q = this.searchQuery.trim();
      });
    }
  },
  computed: {
    dataExtraQueryOptions() {
      let extraQueryOptions = {};
      extraQueryOptions = {
        AND: {},
        ORDER: {
          no_docbc: "ASC",
          id_doc: "ASC"
        }
      };

      let andOr = false;

      if (this.filterInput.tanggal !== "") {
        if (this.filterInput.tanggal[0] !== null) {
          extraQueryOptions.AND["tgl_doc[<>]"] = [
            `${moment(this.filterInput.tanggal[0]).format(
              "YYYY-MM-DD"
            )} 00:00:00`,
            `${moment(this.filterInput.tanggal[1]).format(
              "YYYY-MM-DD"
            )} 23:59:59`
          ];
          andOr = true;
        }
      }

      if (this.filterInput.masukKeluar !== "") {
        extraQueryOptions.AND.id_inout = this.filterInput.masukKeluar;
        andOr = true;
      } else {
        extraQueryOptions.AND.id_inout = "-";
        andOr = true;
      }

      if (this.filterInput.tujuan !== "" && this.filterInput.tujuan !== null) {
        extraQueryOptions.AND.id_tujuan = this.filterInput.tujuan;
        andOr = true;
      }

      if (this.filterInput.jenis !== "" && this.filterInput.jenis !== null) {
        extraQueryOptions.AND.id_type = this.filterInput.jenis;
        andOr = true;
      }

      if (this.q !== "") {
        extraQueryOptions.AND.OR = {};
        this.columns.forEach(item => {
          extraQueryOptions.AND.OR[`${item.value}[~]`] = this.q;
        });
      }

      if (!andOr) {
        delete extraQueryOptions.AND;
      }

      return extraQueryOptions;
    },
    appSettings() {
      return this.$store.state.app.appSettings;
    },
    authenticated() {
      return this.$store.state.auth.authenticated;
    },
    user() {
      return this.$store.state.auth.user;
    },
    windowSize() {
      return this.$store.state.app.windowSize;
    },
    labelPeriode() {
      let label = "KESELURUHAN";

      if (this.filterInput.tanggal[0] !== null) {
        label = `${moment(this.filterInput.tanggal[0]).format(
          "DD/MM/YYYY"
        )}    S/D    ${moment(this.filterInput.tanggal[1]).format(
          "DD/MM/YYYY"
        )}`;
      }
      return label;
    },
    labelMasukKeluar() {
      let label = "Masuk";

      if (this.filterInput.masukKeluar !== "") {
        const filterLabel = _filter(
          this.dpDropdown[0],
          o => o.id_inout === this.filterInput.masukKeluar
        );
        if (filterLabel.length > 0) {
          label = filterLabel[0].movement;
        }
      }

      label = label === "Masuk" ? "PEMASUKAN" : "PENGELUARAN";
      return label;
    },
    dpDropdownQueryOptions() {
      return [
        {
          "id_inout[!]": -1
        },
        {
          "id_type[!]": -1
        },
        {
          "id_tujuan[!]": -1
        }
      ];
    },
    jenisQueryOptions() {
      return {
        movement_type_id: this.filterInputTmp.masukKeluar
      };
    },
    settingPrintQueryOptions() {
      return [
        {
          periode: moment(this.filterInput.tanggal[1]).format("YYYYMM"),
          jenis: "pabean"
        }
      ];
    },
    settingPrint() {
      let data = {};
      if (this.settingPrintModel[0]) {
        if (this.settingPrintModel[0].length > 0) {
          data = this.settingPrintModel[0][0];
        } else {
          data = {
            periode: "",
            tempat: "Bekasi",
            tanggal: new Date(),
            nama: "Dedi Kusnanto",
            jabatan: "Kuasa Direksi"
          };
        }
      }
      return data;
    }
  }
};
</script>
<style scoped>
</style>



